import { decryptAESGCMPBKDF } from "@lecturedoc2/libcrypto";
import * as QRCode from "./qr-canvas.js";
import { quizStyles } from "./quiz-styles.js";
import {
  PROTOCOL_VERSION,
  PROTOCOL_MISMATCH,
  isCompatibleProtocol,
  protocolMismatchMessage,
} from "./protocol.js";

/**
 * One config fetch per server, shared by every <ld-quiz> on the page.
 *
 * A slide deck can easily carry a dozen quizzes; without this, each one would
 * repeat the same request at the same moment. Promises are cached rather than
 * results, so concurrent callers coalesce instead of racing.
 *
 * @type {Map<string, Promise<object>>}
 */
const configCache = new Map();

/** http(s) -> ws(s); an already-absolute ws:// URL is left alone. */
function toWebSocketUrl(url) {
  return url.replace(/^http/, "ws");
}

function withQuery(url, params) {
  const resolved = new URL(url);
  for (const [key, value] of Object.entries(params)) {
    resolved.searchParams.set(key, String(value));
  }
  return resolved.href;
}

/**
 * Ask the quiz server where its own endpoints are.
 *
 * Every URL the component needs used to be hardcoded to a domain root, which
 * quietly ruled out any deployment behind a path prefix -- the common case when
 * a quiz server is mounted inside an existing site. One request now answers all
 * of them, and answers them for the *running* server rather than for whatever
 * layout the component happened to be built against.
 *
 * There is deliberately no fallback to a hardcoded layout. A server that cannot
 * answer this is a server this component cannot talk to, and saying so here is
 * better than guessing an endpoint and failing later with a broken WebSocket.
 *
 * @throws {Error} if the server does not answer, or answers unusably.
 */
async function fetchConfig(base) {
  const endpoint = new URL("/api/config", base);

  let response;
  try {
    response = await fetch(endpoint, { credentials: "omit" });
  } catch (cause) {
    throw new Error(`Cannot reach the quiz server at ${base}.`, { cause });
  }
  if (!response.ok) {
    throw new Error(
      `The quiz server at ${base} did not answer ${endpoint.pathname} ` +
        `(HTTP ${response.status}). Is server-url pointing at a quiz server?`,
    );
  }

  const raw = await response.json();
  if (!raw || typeof raw !== "object") {
    throw new Error(`The quiz server at ${base} returned an unusable configuration.`);
  }

  const required = ["ws", "join", "control", "katexCss"];
  const missing = required.filter((key) => typeof raw[key] !== "string" || raw[key] === "");
  if (missing.length > 0) {
    throw new Error(
      `The quiz server at ${base} did not publish: ${missing.join(", ")}.`,
    );
  }

  return {
    protocolVersion: raw.protocolVersion,
    serverVersion: raw.serverVersion,
    wsUrl: toWebSocketUrl(new URL(raw.ws, base).href),
    joinUrl: new URL(raw.join, base).href,
    controlUrl: new URL(raw.control, base).href,
    katexCssUrl: new URL(raw.katexCss, base).href,
    maxQuizSize: raw.maxQuizSize,
  };
}

function loadConfig(base) {
  let pending = configCache.get(base);
  if (!pending) {
    pending = fetchConfig(base);
    // A failed lookup must not be cached: the server may simply have been
    // restarting, and every later <ld-quiz> on the page would inherit the
    // failure for the lifetime of the document.
    pending.catch(() => configCache.delete(base));
    configCache.set(base, pending);
  }
  return pending;
}

/**
 * Apply the component's stylesheet to a shadow root.
 *
 * A constructed stylesheet is a JavaScript object rather than markup, so it is
 * not covered by the CSP `style-src` directive. Injecting the same CSS as a
 * <style> element requires 'unsafe-inline' on the embedding page, a concession
 * no sensibly configured host (a Moodle site, say) should have to make in order
 * to show a quiz.
 */
function applyStyles(shadowRoot, cssText) {
  const sheet = new CSSStyleSheet();
  sheet.replaceSync(cssText);
  shadowRoot.adoptedStyleSheets = [...shadowRoot.adoptedStyleSheets, sheet];
}

/**
 * Link an external stylesheet into a shadow root.
 *
 * Used for KaTeX, which is linked rather than inlined on purpose: its @font-face
 * rules carry relative URLs, and a copy of the text would resolve those against
 * the embedding page instead of the quiz server -- silently replacing every
 * formula with a fallback font in precisely the cross-origin setup this
 * component exists to support. A <link> keeps the stylesheet's own URL as the
 * base, and asks the host page for `style-src <quiz-host>` instead of
 * 'unsafe-inline'.
 *
 * Resolves either way: missing math CSS makes formulas ugly, which is no reason
 * to refuse to run the quiz.
 */
function linkStylesheet(shadowRoot, href) {
  return new Promise((resolve) => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = href;
    link.addEventListener("load", () => resolve(true), { once: true });
    link.addEventListener(
      "error",
      () => {
        console.warn(`loading the math stylesheet failed: ${href}`);
        resolve(false);
      },
      { once: true },
    );
    shadowRoot.appendChild(link);
  });
}

class QuizHost extends HTMLElement {
  /**
   * Minimum length of the presenter name. The name is what separates two
   * lecturers running the same quiz file, so it has to be long enough to be
   * deliberate -- but it is an isolation key, not a secret.
   */
  static MIN_PRESENTER_NAME_LENGTH = 4;

  constructor() {
    super();
    this.presenterName = null;
    this.presenterToken = null;
    this.attachShadow({ mode: "open" });
    this.quiz = null;
    this.isEncrypted = undefined;
    this.ws = null;
    this.roomId = null;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectDelay = 1000;
    this.currentState = "login";
    this.serverUrl = "";
    /** Endpoint layout of the quiz server; filled in by connectedCallback(). */
    this.config = null;
    /** Presenter name supplied by the slide set; see prefillPresenterName(). */
    this.presenterNameHint = "";
  }

  async connectedCallback() {
    this.quiz = this.getAttribute("quiz");
    this.isEncrypted = this.hasAttribute("encrypted");
    this.serverUrl = this.getAttribute("server-url") || window.location.origin;
    this.presenterNameHint = (this.getAttribute("presenter-name") || "").trim();

    // The styles travel with the code rather than being fetched from the
    // server, so a bundled copy of the component can never be painted with a
    // different release's CSS. See quiz-styles.js.
    applyStyles(this.shadowRoot, quizStyles);

    const container = document.createElement("div");
    container.className = "quiz-container";
    this.contentEl = document.createElement("div");
    this.contentEl.id = "content";
    container.appendChild(this.contentEl);
    this.shadowRoot.appendChild(container);

    if (!window.isSecureContext) {
      this.showError("Quizzy requires a secure context (https, or localhost / 127.0.0.1 / [::1]).");
      return;
    }

    try {
      this.config = await loadConfig(this.serverUrl);
    } catch (e) {
      console.error("loading the quiz server configuration failed", e);
      this.showError(e.message);
      return;
    }

    // Refuse early and legibly. Without this the mismatch would surface as
    // whichever field the two sides first disagree about, in a lecture hall,
    // with an audience watching.
    if (!isCompatibleProtocol(this.config.protocolVersion)) {
      this.showError(protocolMismatchMessage(this.config.protocolVersion));
      return;
    }

    if (this.config.katexCssUrl) {
      linkStylesheet(this.shadowRoot, this.config.katexCssUrl);
    }

    if (this.isEncrypted) {
      // Encrypted inline quiz
      if (!this.quiz) {
        this.showError("No encrypted quiz provided.");
        return;
      }
      this.renderLogin();
    } else if (this.quiz) {
      // Unencrypted inline quiz
      try {
        this.quiz = JSON.parse(this.quiz);
        this.renderQuizPreview();
      } catch (e) {
        this.showError("Invalid quiz JSON");
        console.error("processing json failed", this.quiz, e);
      }
    } else {
      // Unencrypted file upload
      this.renderFileUpload();
    }
  }

  disconnectedCallback() {
    try {
      if (this.ws) {
        this.ws.close();
      }
    } catch (e) {
      console.error("closing websocket connection failed", e);
    }
  }

  renderLogin() {
    this.currentState = "login";
    this.contentEl.innerHTML = `
      <h2 class="quiz-title">Quiz Login</h2>
      <form class="quiz-form" id="login-form">
        <input type="text" class="quiz-input" id="presenter-name" placeholder="Your name (at least 4 characters)"
               autocomplete="off" autocapitalize="off" spellcheck="false" minlength="${QuizHost.MIN_PRESENTER_NAME_LENGTH}">
        <input type="password" class="quiz-input" id="password" placeholder="Enter your password" autocomplete="off">
        <button type="submit" class="quiz-btn quiz-btn-primary">Start Quiz</button>
      </form>
      <div class="quiz-info">Use the same name again to reattach to a running session.</div>
      <div id="error" class="quiz-error" style="display:none"></div>
    `;

    const form = this.shadowRoot.getElementById("login-form");
    const nameInput = this.shadowRoot.getElementById("presenter-name");
    const passwordInput = this.shadowRoot.getElementById("password");
    const errorEl = this.shadowRoot.getElementById("error");

    this.prefillPresenterName(nameInput);

    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      const password = passwordInput.value;
      if (!password) return;

      const name = QuizHost.normalizePresenterName(nameInput.value);
      if (name.length < QuizHost.MIN_PRESENTER_NAME_LENGTH) {
        errorEl.textContent = `Please enter a name of at least ${QuizHost.MIN_PRESENTER_NAME_LENGTH} characters.`;
        errorEl.style.display = "block";
        return;
      }

      errorEl.style.display = "none";
      passwordInput.disabled = true;
      nameInput.disabled = true;
      form.querySelector("button").textContent = "Decrypting...";

      try {
        this.quiz = JSON.parse(await decryptAESGCMPBKDF(this.quiz, password));
        this.presenterName = name;
        QuizHost.savePresenterName(nameInput.value);
        await this.connectWebSocket();
      } catch (e) {
        console.error("decrypting quiz failed", e);
        errorEl.textContent = "Invalid password or corrupted quiz data";
        errorEl.style.display = "block";
        passwordInput.disabled = false;
        nameInput.disabled = false;
        form.querySelector("button").textContent = "Start Quiz";
      }
    });
  }

  /**
   * Normalize a presenter name so that trivial typing differences still resolve
   * to the same session. Without this, "Michael " and "michael" would derive
   * different tokens and the second one would silently fail to reattach.
   */
  static normalizePresenterName(name) {
    return String(name || "")
      .normalize("NFKC")
      .trim()
      .replace(/\s+/g, " ")
      .toLowerCase();
  }

  /**
   * Remember the presenter name -- and only the name, never the password or the
   * token -- so that reopening a session is one field shorter.
   *
   * localStorage, not sessionStorage: sessionStorage dies with the browser,
   * which is precisely the crash case this is meant to help with. The name is
   * not a secret (on its own it grants nothing: the token also requires the
   * decrypted quiz, and therefore the password), so persisting it costs nothing
   * in confidentiality and restores the one piece of state a crash destroys.
   *
   * On a shared lecture-hall machine this does leave the previous presenter's
   * name in the field; it is overwritten by simply typing another one.
   */
  static savePresenterName(name) {
    try {
      localStorage.setItem("ld-quiz-presenter-name", name);
    } catch {
      /* storage unavailable or disabled -- not worth failing over */
    }
  }

  static loadPresenterName() {
    try {
      return localStorage.getItem("ld-quiz-presenter-name") || "";
    } catch {
      return "";
    }
  }

  /**
   * Derive the presenter token from the presenter's name *and* the quiz.
   *
   * The name matters for isolation, not for secrecy. Deriving the token from
   * the quiz alone meant that two lecturers running the same quiz file shared
   * one token -- and therefore each other's sessions. Mixing in the name gives
   * colleagues who swap quiz files distinct tokens, while a lecturer who types
   * the same name again reproduces their own token and reattaches.
   *
   * The separator cannot occur in the normalized name, so ("ab", "c...") and
   * ("a", "bc...") cannot collide.
   *
   * The padStart is essential, not cosmetic: without it every byte below 0x10
   * contributes a single hex character, which both shortens the token and makes
   * the encoding ambiguous (distinct digests can map to the same string). It
   * also keeps this in step with the SHA-256 hex encoding used elsewhere
   * (rooms.js).
   */
  async hashQuiz(quiz, presenterName) {
    const encoder = new TextEncoder();
    const name = QuizHost.normalizePresenterName(presenterName);
    const data = encoder.encode(`${name}\u0000${JSON.stringify(quiz)}`);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  renderQuizPreview() {
    this.currentState = "preview";
    this.contentEl.innerHTML = `
      <div class="quiz-preview">
        <h2 class="quiz-title">${this.escapeHtml(this.quiz.title || "Quiz")}</h2>
        <div class="quiz-meta">${this.quiz.questions.length} questions</div>
        ${QuizHost.presenterNameFieldHtml()}
        <button class="quiz-btn quiz-btn-primary" id="btn-start">Start Quiz</button>
        <div id="name-error" class="quiz-error" style="display:none"></div>
      </div>
    `;

    this.bindPresenterNameField();
    const btnStart = this.shadowRoot.getElementById("btn-start");
    btnStart.addEventListener("click", () => this.startWithPresenterName());
  }

  /** The presenter-name input, shared by every entry path. */
  static presenterNameFieldHtml() {
    return `
      <input type="text" class="quiz-input" id="presenter-name"
             placeholder="Your name (at least ${QuizHost.MIN_PRESENTER_NAME_LENGTH} characters)"
             autocomplete="off" autocapitalize="off" spellcheck="false">
      <div class="quiz-info">Use the same name again to reattach to a running session.</div>`;
  }

  bindPresenterNameField() {
    this.prefillPresenterName(this.shadowRoot.getElementById("presenter-name"));
  }

  /**
   * Fill in the presenter name, preferring the `presenter-name` attribute over
   * whatever this browser last remembered.
   *
   * The name is an isolation key, not a secret: it is what separates two
   * lecturers running the same quiz file, and reproducing it exactly is what
   * lets a presenter reattach to their own running session after a crash.
   * Typing it slightly differently is therefore the failure this attribute
   * exists to prevent -- and since a slide set is nearly always presented by
   * the person who wrote it, the slide set is the right place to state it.
   *
   * The attribute wins over the remembered value because it is a deliberate
   * statement about this deck, whereas localStorage holds whatever the last
   * person at this lectern happened to type.
   */
  prefillPresenterName(input) {
    if (!input) return;
    const name = this.presenterNameHint || QuizHost.loadPresenterName();
    if (name) input.value = name;
  }

  /**
   * Validate the presenter name and open the session. Shared by the preview and
   * upload paths; the encrypted path validates earlier because it must do so
   * before spending time on key derivation.
   */
  async startWithPresenterName() {
    const input = this.shadowRoot.getElementById("presenter-name");
    const errorEl = this.shadowRoot.getElementById("name-error");
    const name = QuizHost.normalizePresenterName(input ? input.value : "");

    if (name.length < QuizHost.MIN_PRESENTER_NAME_LENGTH) {
      if (errorEl) {
        errorEl.textContent = `Please enter a name of at least ${QuizHost.MIN_PRESENTER_NAME_LENGTH} characters.`;
        errorEl.style.display = "block";
      }
      return;
    }

    if (errorEl) errorEl.style.display = "none";
    this.presenterName = name;
    QuizHost.savePresenterName(input.value);
    await this.connectWebSocket();
  }

  renderFileUpload() {
    this.currentState = "upload";
    this.contentEl.innerHTML = `
      <div class="quiz-upload">
        <h2 class="quiz-title">Upload Quiz</h2>
        <p class="quiz-info">Select a JSON quiz file to upload</p>
        <label class="quiz-file-label">
          <input type="file" class="quiz-file-input" id="quiz-file" accept=".json">
          <span class="quiz-file-btn">Choose File</span>
        </label>
        <div id="quiz-file-name" class="quiz-file-name"></div>
        <div id="quiz-preview" class="quiz-preview-container" style="display:none"></div>
        <div id="error" class="quiz-error" style="display:none"></div>
      </div>
    `;

    const fileInput = this.shadowRoot.getElementById("quiz-file");
    const fileName = this.shadowRoot.getElementById("quiz-file-name");
    const previewContainer = this.shadowRoot.getElementById("quiz-preview");
    const errorEl = this.shadowRoot.getElementById("error");

    fileInput.addEventListener("change", async (e) => {
      const file = e.target.files[0];
      if (!file) return;

      errorEl.style.display = "none";
      fileName.textContent = file.name;

      try {
        const text = await file.text();
        const quiz = JSON.parse(text);
        this.quiz = quiz;

        // Show preview
        previewContainer.style.display = "block";
        previewContainer.innerHTML = `
          <h3 class="quiz-title">${this.escapeHtml(quiz.title || "Quiz")}</h3>
          <div class="quiz-meta">${quiz.questions.length} questions</div>
          ${QuizHost.presenterNameFieldHtml()}
          <button class="quiz-btn quiz-btn-primary" id="btn-start-upload">Start Quiz</button>
          <div id="name-error" class="quiz-error" style="display:none"></div>
        `;

        this.bindPresenterNameField();
        const btnStart = this.shadowRoot.getElementById("btn-start-upload");
        btnStart.addEventListener("click", () => this.startWithPresenterName());
      } catch (e) {
        console.error("failed processing JSON file", e);
        errorEl.textContent = "Invalid JSON file";
        errorEl.style.display = "block";
        previewContainer.style.display = "none";
      }
    });
  }

  async connectWebSocket() {
    // Derived once, then reused across reconnects. Both inputs are stable for
    // the lifetime of the session, and reproducing the same token is precisely
    // what lets a reconnect reattach instead of opening a second room.
    if (!this.presenterToken) {
      this.presenterToken = await this.hashQuiz(this.quiz, this.presenterName);
    }

    const config = this.config;
    this.ws = new WebSocket(config.wsUrl);

    this.ws.onopen = () => {
      this.reconnectAttempts = 0;
      const payload = JSON.stringify({
        type: "create_room",
        protocolVersion: PROTOCOL_VERSION,
        presenterToken: this.presenterToken,
        quiz: this.quiz,
      });
      const payloadSize = new TextEncoder().encode(payload).length;
      if (payloadSize > config.maxQuizSize) {
        const limitMb = (config.maxQuizSize / (1024 * 1024)).toFixed(1);
        this.showError(`Quiz data exceeds the server's maximum size of ${limitMb}MB`);
        this.ws.close();
        return;
      }
      this.ws.send(payload);
    };

    this.ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      this.handleMessage(msg);
    };

    this.ws.onclose = () => {
      if (
        this.currentState !== "ended" &&
        this.reconnectAttempts < this.maxReconnectAttempts
      ) {
        setTimeout(() => {
          this.reconnectAttempts++;
          // Reconnecting re-sends create_room, which the server treats as
          // create-or-resume, so this reattaches to the same room rather than
          // stranding everyone who already joined.
          this.connectWebSocket().catch((err) =>
            console.error("reconnect failed", err),
          );
        }, this.reconnectDelay * this.reconnectAttempts);
      }
    };

    this.ws.onerror = (err) => {
      console.error("WebSocket error:", err);
    };
  }

  handleMessage(msg) {
    switch (msg.type) {
      case "error":
        // A rejected handshake is permanent: retrying it four more times only
        // delays the message the presenter needs to read.
        if (msg.code === PROTOCOL_MISMATCH) {
          this.currentState = "ended";
        }
        this.showError(msg.message || "An error occurred");
        break;

      case "room_created":
        this.roomId = msg.roomId;
        if (msg.resumed) {
          console.info(
            `Reattached to running session ${msg.roomId} ` +
              `(state: ${msg.state}, participants: ${msg.participantCount}).`,
          );
        }
        // The server scrubs quiz markup it considers unsafe. Say so loudly:
        // silently dropping part of a question would be worse than the markup.
        if (Array.isArray(msg.warnings) && msg.warnings.length > 0) {
          console.warn(
            `Quizzy removed markup from this quiz (${msg.warnings.length} item(s)):\n  ` +
              msg.warnings.join("\n  "),
          );
        }
        this.renderLobby();
        this.openControlWindow();
        break;

      case "participant_joined":
        this.updateParticipantCount(msg.count);
        break;

      case "participant_left":
        this.updateParticipantCount(msg.count);
        break;

    }
  }

  renderLobby() {
    this.currentState = "lobby";
    const joinUrl = withQuery(this.config.joinUrl, { room: this.roomId });

    this.contentEl.innerHTML = `
      <div class="quiz-lobby">
        <h2 class="quiz-title">${this.quiz.title || "Quiz"}</h2>
        <div class="quiz-participant-count">Participants: <span id="count">0</span></div>
        <div class="quiz-qr-container">
          <canvas id="qr-canvas"></canvas>
        </div>
        <div class="quiz-join-url">${joinUrl}</div>
        <div class="quiz-info">Room: ${this.roomId}</div>
        <div class="quiz-controls">
          <button class="quiz-btn quiz-btn-secondary" id="btn-control">Open Control Window</button>
        </div>
      </div>
    `;

    const canvas = this.shadowRoot.getElementById("qr-canvas");
    QRCode.toCanvas(canvas, joinUrl, {
      width: 256,
      margin: 4,
      errorCorrectionLevel: "Q",
      colorDark: "#1e293b",
      colorLight: "#ffffff",
    });

    const btnControl = this.shadowRoot.getElementById("btn-control");
    btnControl.addEventListener("click", () => this.openControlWindow());
  }

  updateParticipantCount(count) {
    const countElement = this.shadowRoot.getElementById("count");
    if (countElement) countElement.textContent = count;
  }

  openControlWindow() {
    const controlUrl = withQuery(this.config.controlUrl, {
      token: this.presenterToken,
      room: this.roomId,
    });
    console.log(`opening control window`, controlUrl);
    const popup = window.open(
      controlUrl,
      "quiz-control",
      "width=900,height=700,scrollbars=yes",
    );
  }

  showError(message) {
    this.contentEl.innerHTML = `<div class="quiz-error">${this.escapeHtml(message)}</div>`;
  }

  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
}

/**
 * Register the custom element, at most once per tag name.
 *
 * `customElements.define` throws on a name that is already taken, and the throw
 * aborts whatever module is executing. That is not a hypothetical here: the
 * intended deployments are a slide framework that bundles this component and a
 * host page that loads the hosted script, and a page combining the two -- a
 * LectureDoc2 deck embedded in a Moodle course, say -- would load both copies.
 * The second one must yield quietly rather than take the page down with it.
 *
 * The tag name is a parameter because the element is now published for other
 * projects to embed, and a name registered globally is a name they cannot have
 * back if it collides with one of their own.
 *
 * @param {string} [tagName] 
 * @returns {CustomElementConstructor} Whatever now owns the name.
 */
export function defineLdQuiz(tagName = "ld-quiz") {
  const registered = customElements.get(tagName);
  if (registered) {
    if (registered !== QuizHost) {
      console.error(
        `<${tagName}> is already registered by a different implementation; ` +
          "this copy of ld-quiz will not replace it. " +
          "Pass another tag name to defineLdQuiz() if both are needed.",
      );
    }
    return registered;
  }
  customElements.define(tagName, QuizHost);
  return QuizHost;
}

export { QuizHost, PROTOCOL_VERSION };

// Importing this module registers <ld-quiz>; the package declares it as having
// side effects for exactly this reason. Consumers that want a different tag name
// import { defineLdQuiz } and call it themselves -- the default registration
// below is idempotent, so doing both is harmless.
defineLdQuiz();
